mapper.update:
UPDATE t_commerce_order SET version=version+1,update_time=#{now}

    ,tax_amount=#{quote.taxAmount},rounding_amount=#{quote.roundingAmount},total_amount=#{quote.totalAmount},
    amount_status=#{amountStatus}

WHERE order_id=#{order.orderId} AND version=#{order.version}
AND order_status IN ('CREATED','OPEN') AND termination_requested_at IS NULL
AND paid_at IS NULL AND expires_at > #{now}
AND NOT EXISTS (SELECT 1 FROM t_consumer_acceptance a JOIN t_consumer_contract c
ON c.consumer_contract_id=a.consumer_contract_id WHERE c.order_id=#{order.orderId})
AND EXISTS (SELECT 1 FROM t_checkout_session s
WHERE s.checkout_session_id=#{session.checkoutSessionId} AND s.order_id=#{order.orderId}
AND s.version=#{session.version} AND s.session_status IN ('PREPARING','OPEN'))

UPDATE t_commerce_order SET termination_requested_at=#{now},version=version+1,update_time=#{now}
WHERE order_id=#{order.orderId} AND client_id=#{order.clientId} AND version=#{order.version}
AND order_status IN ('CREATED','OPEN') AND termination_requested_at IS NULL

UPDATE t_commerce_order SET order_status='PAID',paid_at=#{paidAt},version=version+1,update_time=#{now}
WHERE order_id=#{order.orderId} AND client_id=#{order.clientId} AND version=#{order.version}
    AND order_status='OPEN' AND paid_at IS NULL

UPDATE t_commerce_order SET order_status='CANCELLED',status_reason_code='CLIENT_REQUESTED',
cancelled_at=#{now},version=version+1,update_time=#{now}
WHERE order_id=#{order.orderId} AND client_id=#{order.clientId} AND version=#{order.version}
AND order_status IN ('CREATED','OPEN') AND termination_requested_at IS NOT NULL AND paid_at IS NULL


        AND EXISTS (
        SELECT 1 FROM t_order_payment_projection p
        WHERE p.order_id=#{order.orderId} AND p.payment_intent_id=#{payment.paymentIntentId}
        AND p.version=#{payment.version} AND p.successful_attempt_id IS NULL
        AND p.captured_amount=0 AND p.intent_status <> 'SUCCEEDED'
        )



            AND NOT EXISTS (SELECT 1 FROM t_consumer_acceptance a JOIN t_consumer_contract c
            ON c.consumer_contract_id=a.consumer_contract_id WHERE c.order_id=#{order.orderId})

        AND NOT EXISTS (SELECT 1 FROM t_order_payment_projection p WHERE p.order_id=#{order.orderId})

