SELECT order_id FROM t_commerce_order
WHERE order_status IN ('CREATED','OPEN') AND expires_at <= #{now} AND order_id > #{afterOrderId}
    AND MOD(order_id, #{shardTotal}) = #{shardIndex}
ORDER BY order_id LIMIT #{limit}

